INSERT INTO public.cms_pages (id, slug, title, subtitle, content, is_published, sort_order, created_at, updated_at) VALUES ('58b7684b-d17d-4a6f-9faa-096c1420aa3f', 'about-us', 'About Us', 'Professional Gaming Boost Services', '[{"type":"hero","heading":"Who We Are","subheading":"Your Trusted Gaming Partner","description":"At misti.services, we are a team of dedicated gaming professionals committed to helping you achieve your gaming goals. With years of experience across multiple titles and a passion for excellence, we deliver premium boosting services that are safe, fast, and reliable."},{"type":"content","content":"<p>We believe every gamer deserves to experience the best their favorite games have to offer. Our mission is to provide top-tier boosting services that save you time while ensuring complete account security and satisfaction.</p><p>Whether you''re looking to reach higher ranks, complete challenging content, or unlock exclusive rewards, our expert team is here to make it happen.</p>","heading":"Our Mission"},{"type":"features","items":[{"icon":"Shield","title":"100% Safe & Secure","description":"Your account security is our top priority. We use VPN protection and never share your information."},{"icon":"Zap","title":"Fast Delivery","description":"Most orders start within 15 minutes. We value your time and deliver results quickly."},{"icon":"Users","title":"Professional Team","description":"Our boosters are experienced players with proven track records in their respective games."},{"icon":"Clock","title":"24/7 Support","description":"Our support team is always available to answer your questions and provide updates."}],"heading":"Why Choose Us"},{"type":"stats","items":[{"label":"Happy Customers","value":"10,000+"},{"label":"Orders Completed","value":"50,000+"},{"label":"Average Rating","value":"5.0"},{"label":"Years Experience","value":"5+"}]}]', true, 0, '2025-10-21T15:26:01.113358+00:00', '2025-10-21T15:26:01.113358+00:00');
