INSERT INTO public.product_faqs (id, product_id, question, answer, sort_order, is_active, generated_by, created_at, updated_at) VALUES ('426507a8-9bf6-44ee-9bb0-32e004e18547', '74440432-6819-4460-8f76-4a563d072d12', 'How quickly can I expect to receive my August Stone Fragments?', 'Our August Stone Fragments Farm Boost has a flexible delivery time, with boosts starting as fast as 15 minutes after your order. The total delivery time depends on the amount of fragments you need, but our professional team works efficiently to get them to you fast.', 0, true, 'ai', '2025-11-21T20:25:55.596045+00:00', '2025-11-21T20:25:55.596045+00:00');
INSERT INTO public.product_faqs (id, product_id, question, answer, sort_order, is_active, generated_by, created_at, updated_at) VALUES ('6f33afa2-31df-465f-b807-449e59c9d803', '74440432-6819-4460-8f76-4a563d072d12', 'Is it safe to use a boosting service for August Stone Fragments in WoW Mists of Pandaria Classic?', 'Yes, your account''s safety is our top priority. We use 100% manual farming methods performed by experienced players, ensuring no bots or automation are involved. This guarantees compliance with game policies and complete account security during the August Stone Fragments farm.', 1, true, 'ai', '2025-11-21T20:25:55.596045+00:00', '2025-11-21T20:25:55.596045+00:00');
INSERT INTO public.product_faqs (id, product_id, question, answer, sort_order, is_active, generated_by, created_at, updated_at) VALUES ('14a230e3-d334-44e1-808b-cf5d9b348840', '74440432-6819-4460-8f76-4a563d072d12', 'What are the requirements for purchasing the August Stone Fragments Farm Boost?', 'To utilize the August Stone Fragments Farm Boost, you simply need an active World of Warcraft subscription and a Level 90 character. If you''re not yet Level 90, we also offer a WoW Power Leveling Boost to get you ready.', 2, true, 'ai', '2025-11-21T20:25:55.596045+00:00', '2025-11-21T20:25:55.596045+00:00');
INSERT INTO public.product_faqs (id, product_id, question, answer, sort_order, is_active, generated_by, created_at, updated_at) VALUES ('fcb9466a-9a41-4738-93fe-931c1aa225d7', '74440432-6819-4460-8f76-4a563d072d12', 'What kind of gear can I get with August Stone Fragments?', 'August Stone Fragments are crucial for acquiring powerful 476–483 ilvl gear and weapons in Mists of Pandaria Classic. Our farming service helps you swiftly gather these fragments, allowing you to quickly gear up your character without the usual grind.', 3, true, 'ai', '2025-11-21T20:25:55.596045+00:00', '2025-11-21T20:25:55.596045+00:00');
INSERT INTO public.product_faqs (id, product_id, question, answer, sort_order, is_active, generated_by, created_at, updated_at) VALUES ('d85bdffd-1046-4f84-bff3-bb9200da88ef', '74440432-6819-4460-8f76-4a563d072d12', 'How does the August Stone Fragments farming process work, and do I have options?', 'After purchasing, our support team will contact you to confirm details. You can choose between our ''Piloted'' option, where a booster logs into your account to farm, or ''Selfplay,'' where you join our team in-game, maintaining control of your character while still benefitting from efficient August Stone Fragments farming.', 4, true, 'ai', '2025-11-21T20:25:55.596045+00:00', '2025-11-21T20:25:55.596045+00:00');
INSERT INTO public.product_faqs (id, product_id, question, answer, sort_order, is_active, generated_by, created_at, updated_at) VALUES ('27910524-c574-4188-b102-475ed361898e', '50edf0f7-cfba-4beb-a5e0-472bf98c86a2', 'What specifically is included in the WoW Pandaria Classic Heroic Dungeons Boost?', 'Our Heroic Dungeon Boost for WoW Pandaria Classic includes completion of all selected heroic dungeons, acquisition of 463 item level gear for your class, the Pandaria Dungeon Hero achievement, and all Justice Points and loot collected during the run. This streamlines your gearing process for pre-raid content.', 0, true, 'ai', '2025-11-21T20:26:06.739909+00:00', '2025-11-21T20:26:06.739909+00:00');
