INSERT INTO public.product_faqs (id, product_id, question, answer, sort_order, is_active, generated_by, created_at, updated_at) VALUES ('41d699eb-85f7-47e4-8bd9-f09c303f5992', '50edf0f7-cfba-4beb-a5e0-472bf98c86a2', 'What are the requirements for me to partake in the MoP Classic Heroic Dungeon Boost?', 'To be eligible for the WoW Pandaria Classic Heroic Dungeon Boost, you need a Level 90 character in Mists of Pandaria Classic and an active WoW subscription. No prior dungeon progress is required, and we can assist with leveling if needed through our Power Leveling Boost.', 3, true, 'ai', '2025-11-21T20:26:06.739909+00:00', '2025-11-21T20:26:06.739909+00:00');
