INSERT INTO public.product_rewards (id, product_id, rewards_content, is_approved, generated_at, approved_at, approved_by, created_at, updated_at) VALUES ('7345f79a-fb06-41c9-91ec-ceebbeae9e40', 'b6b3e826-a628-4349-b8d3-e9212236d73d', '<h4>What You Get</h4><ul><li>Guaranteed delivery of the Diablo 4 Gospel of the Devotee.</li><li>Empower your Necromancer with significantly increased Basic Skill damage and unique enhancements.</li><li>Unlock faster Reap attacks, guaranteed corpse generation from Decompose, explosive Hemorrhage effects, and piercing Bone Splinters.</li><li>Boost your Necromancer''s Intelligence, Maximum Life, and Attack Speed for superior farming and endgame performance.</li><li>Optional upgrades available: choose Greater Affixes for stronger stat bonuses, High Roll Stats for near-maximum potential, or High Roll Unique Power for peak ability performance.</li><li>Enjoy safe, manual delivery through secure in-game trade with VPN protection, ensuring account security.</li><li>Benefit from Misti.Services'' fast, reliable delivery, experienced Diablo 4 specialists, 24/7 live support, and thousands of verified positive reviews.</li><li>Skip the grind of boss farming and get your powerful Unique Focus quickly and hassle-free.</li></ul>', true, '2025-12-12T08:22:25.804+00:00', '2025-12-12T08:26:10.619+00:00', '03765a40-f338-4035-a2ba-8928fff30834', '2025-12-12T08:22:25.836088+00:00', '2025-12-12T08:26:10.670218+00:00');
INSERT INTO public.product_rewards (id, product_id, rewards_content, is_approved, generated_at, approved_at, approved_by, created_at, updated_at) VALUES ('3bc573d6-65b5-4770-b31b-d115d6abbdf7', 'affd735f-ebd8-4445-b00c-9bea7b43317b', '<h4>What You Get</h4><ul><li><strong>Glorious Tyranny weapon enchantment:</strong> Secure this prestigious PvP weapon enhancement.</li><li><strong>2200 Arena rating:</strong> Quickly and safely achieved in 2v2 Arena.</li><li><strong>Full Elite Malevolent Gladiator Set:</strong> Access 483 item level gear and weapons.</li><li><strong>Improved PvP set visuals:</strong> Enhance your character''s elite appearance.</li><li><strong>+600 PvP Power & 50% Disarm Duration Reduction:</strong> Significant functional benefits from the enchantment.</li><li><strong>Fast & efficient completion:</strong> Our expert boosters achieve your goals without endless grinding.</li><li><strong>100% manual & secure gameplay:</strong> No bots or cheats, just professional, strategic play.</li><li><strong>Guaranteed rewards:</strong> All listed enchantments and gear are assured.</li><li><strong>Flexible delivery & quick start:</strong> Service begins within 15 minutes.</li></ul>', true, '2025-12-12T08:51:48.023+00:00', '2025-12-12T09:02:08.376+00:00', '03765a40-f338-4035-a2ba-8928fff30834', '2025-12-12T08:51:48.075977+00:00', '2025-12-12T09:02:08.408466+00:00');
INSERT INTO public.product_rewards (id, product_id, rewards_content, is_approved, generated_at, approved_at, approved_by, created_at, updated_at) VALUES ('0c109e0c-e078-45b1-a242-606ca84652a3', '78dbfe04-41ff-4c00-a3c3-732c3bcaa4b6', '<h4>What You Get</h4><ul><li><b>Thunderfury, Blessed Blade of the Windseeker:</b> The full legendary weapon, secured quickly and efficiently.</li><li><b>Guaranteed Results:</b> We ensure you receive every required item to forge Thunderfury, including both Bindings of the Windseeker and all 10 Elementium Bars.</li><li><b>Molten Core Boss Kills:</b> Ragnaros, Garr, and Baron Geddon defeated, with all related quests completed on your behalf.</li><li><b>Time Savings:</b> Skip the long grind of raids, rare material farming, and complex boss fights. Enjoy a stress-free experience.</li><li><b>Fast & Secure Service:</b> Your boost starts in just 15 minutes, with 100% manual boosting and account protection.</li><li><b>Instant Prestige:</b> Wield one of WoW Classic''s most iconic and powerful weapons, recognized for its legendary power, appearance, and versatility in both PvE and PvP.</li><li><b>Flexible Delivery:</b> Enjoy a convenient boosting process tailored to your schedule.</li></ul>', true, '2025-12-12T08:08:44.112+00:00', '2025-12-12T08:11:06.99+00:00', '03765a40-f338-4035-a2ba-8928fff30834', '2025-12-12T08:08:44.159904+00:00', '2025-12-12T08:11:07.081881+00:00');
INSERT INTO public.product_rewards (id, product_id, rewards_content, is_approved, generated_at, approved_at, approved_by, created_at, updated_at) VALUES ('d50aea4a-b16a-4177-8b23-81b9f213e624', '11c50335-e6b5-4704-b2bb-10663ec598a0', '<h4>What You Get</h4><ul><li><strong>Shadowflame Shalewing Mount:</strong> Instantly unlock this exclusive flying mount.</li><li><strong>Glory of the Aberrus Raider (Meta-Achievement):</strong> All challenging required achievements completed.</li><li><strong>Aberrus, the Shadowed Crucible Raid Clear:</strong> Full normal difficulty clear, including the Aberrus, the Shadowed Crucible achievement.</li><li><strong>High Item Level Gear:</strong> Chance to obtain 415–424 ilvl gear, including Class Tier Set and socketed items.</li><li><strong>115 Achievement Points:</strong> Boost your in-game profile.</li><li><strong>Fast & Efficient Service:</strong> Guaranteed completion within 1 day, with a start time in just 15 minutes.</li><li><strong>Flexible Boost Options:</strong> Choose between Account Sharing, Selfplay, or Remote Control for your convenience.</li><li><strong>Expert Team Support:</strong> Benefit from experienced WoW professionals and 24/7 customer service.</li><li><strong>100% Safe & Reliable:</strong> Your account security is our top priority.</li></ul>', true, '2025-12-12T08:33:16.906+00:00', '2025-12-12T08:40:08.667+00:00', '03765a40-f338-4035-a2ba-8928fff30834', '2025-12-12T08:33:16.937824+00:00', '2025-12-12T08:40:08.730049+00:00');
INSERT INTO public.product_rewards (id, product_id, rewards_content, is_approved, generated_at, approved_at, approved_by, created_at, updated_at) VALUES ('99c2e41a-7d62-4160-a897-bdbf33efcdaf', '5095f11f-8528-4b84-b3d1-f5393e66f7d8', '<h4>What You Get</h4><ul><li><strong>Exclusive Delver’s Mana-Skimmer Mount:</strong> Secure this stunning, customizable astral-themed flying mount in just 3 hours.</li><li><strong>“This Machine Flies?! Don’t Care I Got It!” Achievement:</strong> Earn this prestigious achievement for your character.</li><li><strong>Full Repossessed Questline Completion:</strong> Our experts handle the entire time-consuming quest chain from start to finish.</li><li><strong>All Loot & Gold:</strong> Keep all items, gold, and resources collected during the boost.</li><li><strong>Guaranteed Account Security:</strong> Experience safe, manual completion by trusted boosters using Piloted or Remote Control options.</li><li><strong>Fast Service:</strong> Boost starts in just 15 minutes, with full delivery in approximately 3 hours.</li><li><strong>Real-time Updates:</strong> Stay informed with progress reports from our support team.</li><li><strong>Skip the Grind:</strong> Avoid the high-tier Delves grind and enjoy your new mount instantly.</li></ul>', true, '2025-12-12T08:33:08.172+00:00', '2025-12-12T08:40:16.746+00:00', '03765a40-f338-4035-a2ba-8928fff30834', '2025-12-12T08:33:08.20213+00:00', '2025-12-12T08:40:16.792797+00:00');
