INSERT INTO public.products (id, name, slug, short_description, description, how_it_works, requirements, base_price, image_url, badge_text, trust_score, total_reviews, is_active, is_featured, sort_order, created_at, updated_at, category_id, is_slider_product, slider_config, is_manually_popular, total_sales, start_time_text, start_time_value, delivery_text, delivery_value, meta_description, meta_keywords, og_image, canonical_url, image_alt_text, meta_title, parent_link) VALUES ('b9e72666-f385-422c-b1c9-44d4ea84f633', 'Pearlescent Krolusk', 'pearlescent-krolusk', 'The Pearlescent Krolusk is a rare spawn mount found in the K''aresh zone, specifically within the "Untethered Space" phase.  The Challenge: Unlike standard rares, Urmag cannot be seen or engaged in the normal open world. Players must use the Phase Diving ability (unlocked via the zone campaign) to shift into the alternate dimension.', '<h1><strong>Pearlescent Krolusk Mount Boost</strong></h1><p><strong>Hunt the phantom of K''aresh. Secure the shimmering Pearlescent Krolusk without mastering the Phase Diving mechanics.</strong></p><p>The <strong>Pearlescent Krolusk</strong> is a visually stunning ground mount introduced in <em>The War Within</em> Patch 11.2. Distinguished by its translucent, crystalline carapace that shimmers with void energy, it is a prized catch for any collector.</p><p>However, this mount is hidden behind a complex layer of mechanics. It drops exclusively from <strong>Urmag</strong>, a rare elite that only exists within the <strong>Phase Diving</strong> version of the K''aresh zone. To even see him, you must unlock the Reshii Wraps, enter "Untethered Space," and navigate a dangerous environment to find his spawn. With a daily loot lockout and a low drop chance, farming him manually is a test of patience.</p><p>With <strong>misti.services</strong>, you can skip the phase mechanics and the daily disappointment. Our professional team will handle the Phase Diving and rare farming daily, ensuring every possible attempt is made until this ghostly beetle is added to your collection.</p><h2><strong>Service Includes</strong></h2><p>When you purchase the <strong>Pearlescent Krolusk Carry</strong>, we handle the entire farming process. The service guarantees:</p><ul><li><strong>The Mount:</strong> Pearlescent Krolusk permanently added to your collection.</li><li><strong>The Kill:</strong> Guaranteed farming of the rare elite <strong>Urmag</strong> until the mount drops.</li><li><strong>Phase Access:</strong> We handle the <strong>Phase Diving</strong> mechanics required to locate and engage the rare.</li><li><strong>Loot Rights:</strong> You keep all gold, gear, and resources looted during the farming process.</li><li><strong>Manual Service:</strong> 100% hand-played by experienced boosters.</li></ul><h2><strong>Pearlescent Krolusk: All Information</strong></h2><p>The Pearlescent Krolusk is a rare spawn mount found in the K''aresh zone, specifically within the "Untethered Space" phase.</p><p><strong>The Challenge:</strong> Unlike standard rares, <strong>Urmag</strong> cannot be seen or engaged in the normal open world. Players must use the <strong>Phase Diving</strong> ability (unlocked via the zone campaign) to shift into the alternate dimension.</p><ul><li><strong>Drop Chance:</strong> The mount has a low drop rate (estimated ~5-7%).</li><li><strong>Lockout:</strong> You only get one chance for loot per character, per day.</li></ul><p>This combination of a hidden phase and a daily lockout makes it one of the most annoying mounts to farm solo. Our boosters optimize this by tracking Urmag''s spawn timers and utilizing the daily lockouts efficiently to minimize the time it takes to secure your reward.</p><h2><strong>Boost Options Explained</strong></h2><p>We offer two secure methods to deliver your mount:</p><ul><li><strong>Piloted:</strong> Our professional player logs into your account to complete the boost. We utilize strict security protocols, including VPNs matching your country, to ensure your account remains safe and flagged as a local login.</li><li><strong>Remote Control:</strong> For the highest level of security, our booster connects to your PC via a secure application like Parsec. They play the game using your mouse and keyboard while you watch the stream live. Your login credentials are never shared.</li></ul>', '<ul><li><strong>Select Options:</strong> Choose your preferred boost method (Piloted or Remote Control).</li><li><strong>Order Confirmation:</strong> After payment, you will receive an order number and email confirmation.</li><li><strong>Contact:</strong> Our support manager will reach out via Live Chat or Discord to verify your details.</li><li><strong>Assignment:</strong> We assign a professional booster familiar with K''aresh Phase Diving.</li><li><strong>Completion:</strong> The booster farms Urmag daily using your character''s lockouts until the mount drops.</li><li><strong>Enjoy:</strong> We notify you immediately upon completion, and you log in to find the Pearlescent Krolusk in your journal.</li></ul>', '<ul><li><strong>Level:</strong> Level 80 Character.</li><li><strong>Expansion:</strong> The War Within active.</li><li><strong>Account:</strong> Active World of Warcraft subscription.</li><li><strong>Unlock:</strong> K''aresh zone and Phase Diving unlocked (or we can do it for you).</li></ul>', 84.15, 'https://kdjlhibxxygfdmlvdfcl.supabase.co/storage/v1/object/public/game-images/pearlescent-krolusk-1763851658763.webp', NULL, 4.9, 0, true, true, 0, '2025-11-22T19:12:36.995109+00:00', '2025-12-16T07:22:24.158623+00:00', 'b4c0ccaf-a937-4b30-9ab4-7dacee8f739b', false, NULL, true, 0, '15 minutes', 'average start time', 'Flexible', 'order completion', 'Ride the Pearlescent Krolusk across the wastes without endless farming. Order a trusted mount boost from misti.services and enjoy guaranteed results.', 'pearlescent krolusk mount, k''aresh pearlescent krolusk, untethered space mount, phase diving mount, urmag mount rare, buy pearlescent krolusk, pearlescent krolusk boost, k''aresh zone mount, pearlescent krolusk service, rare spawn mount game, game pearlescent krolusk, untethered space phase mount, phase diving ability mount, acquire pearlescent krolusk', 'https://kdjlhibxxygfdmlvdfcl.supabase.co/storage/v1/object/public/game-images/pearlescent-krolusk-1763851658763.webp', NULL, 'Game gaming service - Pearlescent Krolusk', 'War Within Pearlescent Krolusk | misti.services', NULL);
