INSERT INTO public.products (id, name, slug, short_description, description, how_it_works, requirements, base_price, image_url, badge_text, trust_score, total_reviews, is_active, is_featured, sort_order, created_at, updated_at, category_id, is_slider_product, slider_config, is_manually_popular, total_sales, start_time_text, start_time_value, delivery_text, delivery_value, meta_description, meta_keywords, og_image, canonical_url, image_alt_text, meta_title, parent_link) VALUES ('49896428-e437-4281-8799-897d2697f22a', 'Karazhan Attunement', 'karazhan', 'Karazhan is the crown jewel of The Burning Crusade—the first 10-man raid every fresh Level 70 wants to enter. But getting inside is one of the longest, most complex attunement chains in WoW history. You can''t just walk in; you need The Master''s Key.', '<h1><strong>WoW TBC Classic Karazhan Attunement Boost</strong></h1><p><strong>Unlock the Tower of Medivh without the headache. The Master''s Key delivered to your bags.</strong></p><p><a href="https://www.wowhead.com/tbc/guide/karazhan-raid-overview-burning-crusade-classic" rel="noopener noreferrer" target="_blank">Karazhan </a>is the crown jewel of The Burning Crusade—the first 10-man raid every fresh Level 70 wants to enter. But getting inside is one of the longest, most complex attunement chains in WoW history. You can''t just walk in; you need <strong>The Master''s Key</strong>.</p><p>Obtaining this key requires clearing multiple difficult dungeons, obtaining <em>other</em> keys to enter those dungeons, and traveling across Outland. It is a massive time sink. With <strong>misti.services</strong>, you can skip the frustration of finding dungeon groups and let our pros handle the entire <strong>Karazhan Attunement</strong> chain for you.</p><h2><strong>Service Includes</strong></h2><p>We handle every step of the "Arcane Disturbances" questline. When you order the <strong>Karazhan Attunement Boost</strong>, you get:</p><ul><li><strong>The Master''s Key:</strong> Permanent access to the Karazhan raid instance.</li><li><strong>Dungeon Clears:</strong> Full runs of <strong>Shadow Labyrinth</strong>, <strong>The Steamvault</strong>, <strong>The Arcatraz</strong>, <strong>Old Hillsbrad Foothills</strong>, and <strong>The Black Morass</strong>.</li><li><strong>Sub-Key Access:</strong> We complete the requirements to enter The Arcatraz (Key to the Arcatraz) and Shadow Labyrinth (Shadow Labyrinth Key) if needed.</li><li><strong>Reputation:</strong> Gains with <strong>The Violet Eye</strong>, <strong>Keepers of Time</strong>, and <strong>Lower City</strong>.</li><li><strong>Loot &amp; Gold:</strong> You keep all gold, gear, and Primal Nethers that drop for your character during the dungeon runs.</li></ul><h2><strong>The "Master''s Key" Journey: What We Do For You</strong></h2><p>The path to Karazhan is not a straight line. It is a web of requirements. Here is exactly what our boosters handle during your order:</p><p><strong>1. The First Fragment (Shadow Labyrinth)</strong> We locate Khadgar in Shattrath and begin the chain. We secure the <strong>Shadow Labyrinth Key</strong> by defeating Talon King Ikiss, then clear the full Shadow Labyrinth dungeon to loot the First Key Fragment from the Arcane Container behind Murmur.</p><p><strong>2. The Second &amp; Third Fragments (Steamvault &amp; Arcatraz)</strong></p><ul><li><strong>Steamvault:</strong> We clear the dungeon to Hydromancer Thespia to secure the Second Fragment.</li><li><strong>The Arcatraz:</strong> This is the hard part. We handle the lengthy quest chain in Netherstorm (Area 52) to forge the <strong>Key to the Arcatraz</strong>. Once unlocked, we clear the dungeon to Zereketh the Unbound to loot the Third Fragment.</li></ul><p><strong>3. The Black Morass (Opening the Dark Portal)</strong> Finally, we travel to the Caverns of Time. We complete the <strong>Old Hillsbrad Foothills</strong> (saving Thrall from Durnholde Keep) to unlock the <strong>Black Morass</strong>. We then successfully defend Medivh during the Opening of the Dark Portal to finish the chain.</p><h2><strong>Boost Options</strong></h2><ul><li><strong>Piloted (Recommended):</strong> Our professional booster logs into your account using a <strong>VPN matching your country</strong>. They complete the long chain of dungeons while you are offline. This is the most efficient method for complex attunements.</li><li><strong>Remote Control:</strong> For maximum security, our booster connects to your PC via <strong>Parsec</strong>. They play using your mouse and keyboard while you watch the screen live.</li></ul><h2><strong>Why Choose misti.services?</strong></h2><ul><li><strong>Dungeon Experts:</strong> We know the mechanics of Murmur, Aeonus, and Pathaleon by heart. No wiped groups, no wasted time.</li><li><strong>Complete Solution:</strong> We don''t just do the last step; we handle the pre-quests, the flying, and the keys.</li><li><strong>24/7 Support:</strong> Track your attunement progress anytime via our Live Chat.</li></ul><p><strong>Don''t get left outside the raid. Order your WoW TBC Karazhan Attunement Boost today and step into the tower!</strong></p>', '<ul><li>Select your desired options and complete your order on&nbsp;Misti.Services.</li><li>You’ll receive an order confirmation and tracking number via email.</li><li>Our support manager will contact you through live chat to confirm all details.</li><li>If you’re unavailable, we’ll reach out via email or your preferred contact method.</li><li>When the boost is finished, you’ll receive a completion notification on Discord or another messenger of your choice.</li></ul>', '<ul><li><a href="https://misti.services/game/wow-tbc-fresh/leveling/tbc-powerleveling" rel="noopener noreferrer" target="_blank"><strong>Level 70 Character</strong></a><strong>:</strong> You must be max level to begin the specific raid attunement quests.</li><li><strong>Flying Mount:</strong> Required for the Arcatraz portion of the questline.</li><li><strong>WoW TBC Classic Account:</strong> Active subscription.</li></ul>', 85.04, 'https://kdjlhibxxygfdmlvdfcl.supabase.co/storage/v1/object/public/game-images/9i9lr0ebxk7.webp', NULL, 4.9, 0, true, true, 0, '2025-11-21T23:19:55.653042+00:00', '2026-02-17T00:58:34.022725+00:00', '116b15ba-d76a-44a3-b1be-5bcb88c71693', false, NULL, true, 1, '15 minutes', 'average start time', 'Flexible', 'order completion', 'Buy Karazhan Attunement Boost for WoW TBC Classic. We handle Shadow Lab, Arcatraz, and Black Morass runs. Get The Master''s Key fast & safe at misti.services.', 'WoW TBC Karazhan Attunement, Buy The Master''s Key WoW, Karazhan Boost TBC, Arcatraz Key Boost, Black Morass Attunement Service, misti.services TBC,Shadow Labyrinth Key Quest Carry, Opening of the Dark Portal Boost, Khadgar Karazhan Quest Service, TBC Classic Dungeon Boost, Unlock Karazhan Fast', NULL, NULL, 'karazhan attunement', 'WoW TBC Karazhan Attunement | misti.services', NULL);
INSERT INTO public.products (id, name, slug, short_description, description, how_it_works, requirements, base_price, image_url, badge_text, trust_score, total_reviews, is_active, is_featured, sort_order, created_at, updated_at, category_id, is_slider_product, slider_config, is_manually_popular, total_sales, start_time_text, start_time_value, delivery_text, delivery_value, meta_description, meta_keywords, og_image, canonical_url, image_alt_text, meta_title, parent_link) VALUES ('5f9c81f4-a376-4ea2-8b59-d3c0f3719247', 'Fishing', 'wow-tbc-classic-fishing-boost-1-375', 'Fishing is widely considered one of the most time-consuming and tedious professions in World of Warcraft: The Burning Crusade Classic. However, it is also one of the most essential. Whether you are a raider needing high-stat food buffs or a gold farmer looking to profit from rare catches, Fishing is a mandatory secondary profession.', '<h1><strong>WoW TBC Classic Fishing Boost (1-375)</strong></h1><p>Fishing is widely considered one of the most time-consuming and tedious professions in World of Warcraft: The Burning Crusade Classic. However, it is also one of the most essential. Whether you are a raider needing high-stat food buffs or a gold farmer looking to profit from rare catches, Fishing is a mandatory secondary profession.</p><p>At <strong>Misti.services</strong>, we take the boredom out of the bobber watching. We will manually level your Fishing from 1 to 375, complete the lengthy travel quests, and help you obtain the best fishing gear available, allowing you to enjoy the rewards without the hundreds of hours of staring at the water.</p><h2><strong>Why Choose Fishing in TBC?</strong></h2><p>While often overlooked, Fishing is the backbone of the consumable economy and provides unique rewards that cannot be obtained elsewhere.</p><ul><li><strong>Raid Consumables:</strong> Catch the raw materials needed for top-tier Cooking recipes, such as <strong>[Spicy Crawdad]</strong> (Stamina) and <strong>[Poached Bluefish]</strong> (Spell Power).</li><li><strong>Gold Making:</strong> Fish like <strong>[Deviate Fish]</strong> and <strong>[Oily Blackmouth]</strong> are always in high demand for Alchemy and fun consumables.</li><li><strong>Daily Rewards:</strong> Unlocks the Fishing Daily quests in Outland, rewarding rare gems, unique pets, and high-vendor-value trash items.</li><li><strong>Rare Items:</strong> Chance to fish up rare mounts, pets (like <strong>[Magical Crawdad]</strong>), and the elusive <strong>[Mr. Pinchy]</strong>.</li></ul><h2><strong>Fishing Progression Overview</strong></h2><p>Leveling Fishing is unique because it requires not just standing in one spot, but traveling across the world to unlock higher skill caps.</p><h3>1. Apprentice to Expert (1 - 225)</h3><p>The early levels are straightforward but slow.</p><ul><li><strong>Mechanic:</strong> You must purchase a Fishing Pole and apply Baubles to ensure catches.</li><li><strong>The Hurdle:</strong> At skill 150, you cannot simply learn from a trainer. You must travel to Booty Bay to purchase <strong>[Expert Fishing - The Bass and You]</strong>. We handle this travel and purchase for you.</li></ul><h3>2. Artisan Fishing (The Nat Pagle Quest)</h3><p>This is the biggest hurdle for most players. At skill 225, you are required to complete the quest <strong>Nat Pagle, Angler Extreme</strong>.</p><ul><li><strong>The Mission:</strong> Nat Pagle in Dustwallow Marsh requires you to catch 4 specific rare fish from 4 different zones across Azeroth (Feralas, Swamp of Sorrows, Desolace, and Stranglethorn Vale).</li><li><strong>Our Service:</strong> We handle the flight paths, the travel time, and the RNG of catching these specific quest items to unlock your skill cap up to 300.</li></ul><h3>3. Master Fishing (300 - 375)</h3><p>Once you reach Outland, the difficulty spikes.</p><ul><li><strong>The Unlock:</strong> We locate the <strong>[Master Fishing - The Art of Angling]</strong> book in Zangarmarsh to unlock the final tier.</li><li><strong>The Grind:</strong> Fishing in Outland requires a very high skill level to avoid fish "getting away." We utilize the best lures and zones (like the lakes of Terokkar Forest) to push your skill to the maximum of 375.</li></ul><h2><strong>Important Fishing Gear &amp; Unlocks</strong></h2><p>To fish efficiently in TBC, you need more than just a stick and a string. There are specific items that drastically increase your catch rate.</p><h3>Fishing Poles</h3><ul><li><strong>[Seth''s Graphite Fishing Pole]:</strong> (+20 Fishing) A solid starter pole obtained via questing in Shattrath.</li><li><strong>[Nat Pagle''s Extreme Angler FC-5000]:</strong> (+25 Fishing) A Horde-only reward from the Hinterlands.</li><li><strong>[Arcanite Fishing Pole]:</strong> (+35 Fishing) The best-in-slot pole, only obtainable by winning the Stranglethorn Fishing Extravaganza.</li></ul><h3>Fishing Lures &amp; Enhancements</h3><ul><li><strong>[Aquadynamic Fish Attractor]:</strong> (+100 Fishing) Essential for high-level water.</li><li><strong>[Sharpened Fish Hook]:</strong> (+100 Fishing) Obtained from daily quest bags.</li><li><strong>[Spun Truesilver Fishing Line]:</strong> A rare drop that permanently adds stats to your pole.</li></ul><h2><strong>Fishing Dailies (Old Man Barlo)</strong></h2><p>In TBC, a new NPC named <strong>Old Man Barlo</strong> (located near Shattrath City) offers one of five random daily quests.</p><ul><li><strong>The Quests:</strong> <em>Felblood Fillet, Shrimpin'' Ain''t Easy, Bait Bandits, The One That Got Away,</em> and <em>Crocolisks in the City</em>.</li><li><strong>The Reward:</strong> Completing these grants a <strong>[Bag of Fishing Treasures]</strong>, which can contain valuable vendor items, rare cooking recipes, and unique vanity pets.</li></ul><h2><strong>What Our Service Includes</strong></h2><p>When you order a Fishing boost from <strong>Misti.services</strong>, you get a complete package:</p><ul><li><strong>Leveling 1-375:</strong> We perform the thousands of casts required to reach the skill cap.</li><li><strong>Quest Completion:</strong> We complete <em>Nat Pagle, Angler Extreme</em> to unlock Artisan skill.</li><li><strong>Loot Retention:</strong> All fish, items, and locked boxes caught during the process stay in your inventory.</li><li><strong>Secure &amp; Manual:</strong> No bots. We use experienced players and VPN protection to ensure your account safety.</li></ul><p><strong>Ready to become the Master Angler of Outland? Select your current skill level above and let us reel in the rewards for you!</strong></p>', '<ul><li>Select your desired options and complete your order on&nbsp;Misti.Services.</li><li>You’ll receive an order confirmation and tracking number via email.</li><li>Our support manager will contact you through live chat to confirm all details.</li><li>If you’re unavailable, we’ll reach out via email or your preferred contact method.</li><li>When the boost is finished, you’ll receive a completion notification on Discord or another messenger of your choice.</li></ul>', '<ul><li>Level 70 character</li><li>Active WoW Subscription</li></ul>', 0, 'https://kdjlhibxxygfdmlvdfcl.supabase.co/storage/v1/object/public/game-images/wow-tbc-classic-fishing-boost-1-375-1764547147790.webp', NULL, 4.9, 0, true, true, 0, '2025-11-30T23:46:02.022675+00:00', '2026-02-16T10:51:55.877754+00:00', '1dea78b7-88a7-4056-84fb-9f891ece362c', true, '{"step":1,"end_label":"End Value","max_value":375,"min_value":1,"default_end":60,"start_label":"Start Value","default_start":1,"pricing_brackets":[{"end":300,"price":51,"start":1},{"end":375,"price":68,"start":301}],"estimated_time_per_step":0.005}', true, 0, '15 minutes', 'average start time', 'Flexible', 'order completion', 'Skip the tedious grind! We level your Fishing from 1 to 375, complete the Nat Pagle Angler Extreme quest, and unlock Outland dailies. ', 'WoW TBC Fishing boost, Fishing leveling service 1-375, buy WoW fishing skill, Nat Pagle quest boost, TBC Classic fishing guide, Old Man Barlo dailies, Master Fishing book TBC, farming savory deviate delight, WoW classic gold farming, Arcanite Fishing Pole service, Zangarmarsh fishing farm, Mr Pinchy farm, Enormous Barbed Gill Trout, TBC buff food, WoW profession powerleveling', 'https://kdjlhibxxygfdmlvdfcl.supabase.co/storage/v1/object/public/game-images/wow-tbc-classic-fishing-boost-1-375-1764547147790.webp', NULL, 'Wow Tbc Classic Fishing Boost 1 375', 'WoW TBC Classic Fishing Boost | misti.services', NULL);
INSERT INTO public.products (id, name, slug, short_description, description, how_it_works, requirements, base_price, image_url, badge_text, trust_score, total_reviews, is_active, is_featured, sort_order, created_at, updated_at, category_id, is_slider_product, slider_config, is_manually_popular, total_sales, start_time_text, start_time_value, delivery_text, delivery_value, meta_description, meta_keywords, og_image, canonical_url, image_alt_text, meta_title, parent_link) VALUES ('602c3b75-2253-443c-a2f4-7c790c7aa52b', 'Incognitro, the Indecipherable Felcycle', 'incognitro-the-indecipherable-felcycle', 'ncognitro, the Indecipherable Felcycle is a legion-themed motorcycle ground mount introduced as part of WoW’s 20th Anniversary celebration. It is obtained through the Guest Relations secret event, which is built around hidden clues, exploration, and puzzle solving rather than straightforward questing.', '<h1><strong>WoW Incognitro, the Indecipherable Felcycle Mount Boost</strong></h1><p>Get one of the most unique secret mounts released for WoW’s anniversary without spending days solving obscure puzzles.</p><p>With the Incognitro, the Indecipherable Felcycle Mount Boost from misti.services, you unlock an exclusive fel-themed motorcycle ground mount tied to the Guest Relations secret event. Normally, this mount requires following a long chain of hidden clues, secret interactions, and puzzle steps spread across Azeroth. It is a classic Blizzard secret: clever, fun, but extremely time-consuming if you are doing it from scratch.</p><p>Instead of digging through guides and trying to decode every step, you can let our experienced secret-solver team handle it for you. We know the full route, conditions, and hidden requirements, which means Incognitro ends up in your collection quickly and safely while you focus on the content you actually enjoy.</p><h2><strong>Service Includes</strong></h2><p>When you purchase Incognitro, the Indecipherable Felcycle Mount Boost from misti.services, you get a full, done-for-you completion of the entire secret event linked to this mount.</p><p>The service includes:</p><ul><li><strong>Special Keys to Incognitro, the Indecipherable Felcycle</strong> ground mount, unlocking the motorcycle for your account.</li><li><strong>Ratts’ Revenge Feat of Strength achievement</strong> obtained along the way, proving you completed the associated secret content.</li><li>All additional rewards, currency, and items naturally earned during the process kept on your account.</li><li>100% <strong>manual completion</strong> by experienced players who specialize in secret and puzzle content.</li></ul><h2><strong>About Incognitro Mount</strong></h2><p>Incognitro, the Indecipherable Felcycle is a legion-themed motorcycle ground mount introduced as part of WoW’s 20th Anniversary celebration. It is obtained through the <strong>Guest Relations</strong> secret event, which is built around hidden clues, exploration, and puzzle solving rather than straightforward questing.</p><p>To unlock Incognitro, you must:</p><ul><li>Start with the <strong>Lost and Busy</strong> quest from <strong>Alyx</strong> in the Caverns of Time.</li><li>Follow a trail of cryptic hints and secret interactions scattered across Azeroth.</li><li>Use special secret-finding items such as the <strong>Torch of Pyrreth</strong> to reveal hidden clues and progress through the event.</li><li>Complete multiple stages of the puzzle chain, picking up achievements and rewards along the way.</li><li>Finish the full Guest Relations event to earn <strong>Bronze Celebration Tokens</strong>, toys, the <strong>Ratts’ Revenge</strong> Feat of Strength, and finally the keys to Incognitro, the Indecipherable Felcycle.</li></ul><p>On paper, this is an amazing secret experience. In practice, it can easily consume many hours, especially if you make a mistake or miss a step. Our Incognitro mount boost is designed for players who love the reward but do not have time for endless trial and error.</p><p>By choosing misti.services, you get:</p><ul><li>A guaranteed, streamlined path to the mount.</li><li>No need to research every individual riddle or mechanic.</li><li>A professional team that already knows the full solution and route.</li></ul><p>Just place your order, and we handle the rest.</p><h2><strong>Boost Options Explained</strong></h2><p>We offer two secure ways to complete your Incognitro boost, depending on how much control and visibility you prefer:</p><ul><li><strong>Account Sharing (Piloted):</strong></li><li> A professional booster logs into your character and completes all necessary steps for the Guest Relations secret event, including the Lost and Busy quest chain, puzzle stages, and achievement requirements. We follow strict safety practices and treat your account with care.</li><li><strong>Remote Control:</strong></li><li> For maximum transparency, our booster connects to your PC via a secure remote app such as Parsec and plays using your own mouse and keyboard. You watch everything live on your screen while the booster progresses through the entire secret event. Your login details stay with you at all times.</li></ul><p>Both options are fully manual and handled by experienced players familiar with puzzle and secret content.</p>', '<ul><li>You select your preferred options for the Incognitro, the Indecipherable Felcycle Mount Boost on misti.services and complete the purchase.</li><li>You receive an order number and an email confirmation that your boost has been created.</li><li>Our support team reaches out via the website chat; if necessary, we also follow up via email or your preferred messenger to clarify any details.</li><li>You provide any additional information required (character, schedule, chosen boost method), and we assign a suitable booster to your order.</li><li>For <strong>Account Sharing</strong>, the booster logs into your account at the agreed time and completes the Guest Relations secret event, including all puzzle stages, clues, and achievement requirements, until Incognitro is unlocked.</li><li>For <strong>Remote Control</strong>, the booster connects securely to your PC and performs the entire process while you watch.</li><li>Once the boost is complete and you have the keys to Incognitro and the Ratts’ Revenge Feat of Strength, you receive a notification via Discord or another messenger of your choice.</li></ul>', '<ul><li><strong>Level 80 character</strong></li><li><strong>Detective title unlocked</strong></li></ul>', 67.15, 'https://kdjlhibxxygfdmlvdfcl.supabase.co/storage/v1/object/public/game-images/incognitro-the-indecipherable-felcycle-1764152651031.webp', NULL, 4.9, 0, true, true, 0, '2025-11-24T21:29:39.728208+00:00', '2025-12-16T07:22:25.113227+00:00', 'b4c0ccaf-a937-4b30-9ab4-7dacee8f739b', false, NULL, true, 0, '15 minutes', 'average start time', 'Flexible', 'order completion', 'Unlock Incognitro, the Indecipherable Felcycle fast with misti.services. We complete the Guest Relations secret event, puzzles, and requirements for this exclusive 20th A', 'Incognitro mount boost, Indecipherable Felcycle carry, WoW 20th Anniversary mount, Guest Relations secret event, Lost and Busy quest boost, Torch of Pyrreth puzzle, Ratts’ Revenge FoS, detective title mount, WoW motorcycle mount, misti.services WoW boosts', 'https://kdjlhibxxygfdmlvdfcl.supabase.co/storage/v1/object/public/game-images/incognitro-the-indecipherable-felcycle-1764152651031.webp', NULL, 'Incognitro The Indecipherable Felcycle', 'War Within Incognitro Mount | misti.services', NULL);
