INSERT INTO public.service_highlights (id, icon_name, title, description, sort_order, is_active, created_at, updated_at) VALUES ('4d794d21-be35-4110-acd7-cea8f8ad2223', 'CheckCircle', '24/7 Support', 'Our dedicated support team is available around the clock to assist you with any questions or concerns', 0, true, '2025-10-26T19:45:33.442149+00:00', '2025-12-20T21:55:15.859245+00:00');
INSERT INTO public.site_faqs (id, question, answer, sort_order, is_active, created_at, updated_at) VALUES ('7e00faeb-e6e7-42af-a158-db1038358bbe', 'Is my account safe during boosting services?', 'Absolutely! We prioritize account security above all else. Our professional boosters use VPN protection matching your location, follow strict security protocols, and never share your credentials. We also offer offline mode for sensitive accounts.', 1, true, '2026-01-08T08:29:00.790915+00:00', '2026-01-08T08:29:00.790915+00:00');
INSERT INTO public.site_faqs (id, question, answer, sort_order, is_active, created_at, updated_at) VALUES ('91b63681-ce74-4545-a5c4-796dccf2bf2e', 'What payment methods do you accept?', 'We accept all major payment methods including credit/debit cards (Visa, Mastercard, American Express), PayPal, cryptocurrency, and various regional payment options. All transactions are securely processed with industry-standard encryption.', 2, true, '2026-01-08T08:29:00.790915+00:00', '2026-01-08T08:29:00.790915+00:00');
INSERT INTO public.site_faqs (id, question, answer, sort_order, is_active, created_at, updated_at) VALUES ('1f22085b-5654-4c18-a296-280a03a1e517', 'How long does delivery take?', 'Delivery times vary by service type. Most orders begin within 1-24 hours of purchase. Gold and currency deliveries are typically instant to a few hours, while boosting services depend on the scope of work. You can track progress in real-time through your account dashboard.', 3, true, '2026-01-08T08:29:00.790915+00:00', '2026-01-08T08:29:00.790915+00:00');
INSERT INTO public.site_faqs (id, question, answer, sort_order, is_active, created_at, updated_at) VALUES ('f3d04a98-7d3c-4d15-adf9-7fc0c5dfc406', 'What is your refund policy?', 'We offer a satisfaction guarantee on all services. If we cannot complete your order or you are unsatisfied with the service, we provide full or partial refunds depending on the situation. Contact our support team within 48 hours of any issues.', 4, true, '2026-01-08T08:29:00.790915+00:00', '2026-01-08T08:29:00.790915+00:00');
INSERT INTO public.site_faqs (id, question, answer, sort_order, is_active, created_at, updated_at) VALUES ('717c8007-db0b-4915-8b15-edf011c04688', 'Do you offer discounts for returning customers?', 'Yes! We have a cashback loyalty program where you earn cashback on every purchase based on your tier level. You can also use referral codes for additional discounts and check our promotions page for seasonal offers.', 6, true, '2026-01-08T08:29:00.790915+00:00', '2026-01-08T08:29:00.790915+00:00');
INSERT INTO public.site_faqs (id, question, answer, sort_order, is_active, created_at, updated_at) VALUES ('e7a20c3c-72b6-4ee3-90cf-abaed4eb36b0', 'How do I communicate with my booster?', '<p>Once your order is assigned, you can communicate directly with your booster through dedicated Discord server. You will also receive email updates on order progress and can contact our 24/7 support team anytime.</p>', 5, true, '2026-01-08T08:29:00.790915+00:00', '2026-01-08T08:33:25.48327+00:00');
